// Expectations are hand-derived; production Store/Controller/UI/Export bodies
// execute against real SQLite. Synthetic clocks/faults are terminal primitives.
void continuity_seed(PersonalFixture &f,long wanted,const string &payload="NO_SL_DETECTED|-"){
 if(wanted<5){f.open();}else{f.initial();int changed=0;REQUIRE(JPWPersonalPeakAccept(f.capture,"continuity-first-photo",f.current,f.estimated,changed),"seed peak seven");f.commit(changed);}
 long first=scalar(f.context.db,"SELECT sequence FROM ph_meta");REQUIRE(first<=wanted,"fixture lower bound");string digest;JPWPersonalHash(payload,digest);
 REQUIRE(DatabaseTransactionBegin(f.context.db),"fixture bulk transaction");
 int q=DatabasePrepare(f.context.db,"INSERT INTO ph_rows VALUES(?1,'EVENT','bulk',1000,?2,?3)");REQUIRE(q!=-1,"fixture bulk prepare");
 for(long seq=first+1;seq<=wanted;seq++){sqlite3_reset(host_statements.at(q));sqlite3_clear_bindings(host_statements.at(q));REQUIRE(DatabaseBind(q,0,seq)&&DatabaseBind(q,1,payload)&&DatabaseBind(q,2,digest)&&JPWPersonalDone(q),"fixture canonical row");}
 DatabaseFinalize(q);REQUIRE(DatabaseExecute(f.context.db,"UPDATE ph_meta SET sequence="+IntegerToString(wanted)),"fixture exact sequence");REQUIRE(DatabaseTransactionCommit(f.context.db),"fixture commit");f.close();
}
int continuity_drain(JPWPersonalStoreContext &ctx,int rows=1024,int budget=25){
 int db=ctx.db,steps=0,rows_query=-1;
 while(JPWPersonalPreparing(ctx)){
  long prior=ctx.expected_sequence;auto phase=ctx.phase;int query=ctx.query;
  auto result=JPWPersonalOpenStep(ctx,GetTickCount64(),budget,rows,1000,1000000);steps++;
  REQUIRE(ctx.expected_sequence-prior<=rows,"per-slice row budget");
  if(result!=JPW_STORE_BUSY&&result!=JPW_STORE_VALID)break;
  REQUIRE(ctx.db==db,"same live connection across slices");
  if(phase==JPW_PH_ROWS&&ctx.phase==JPW_PH_ROWS&&query!=-1&&ctx.query!=-1)REQUIRE(query==ctx.query,"same journal cursor across slices");
  if(ctx.phase==JPW_PH_ROWS&&ctx.query!=-1)rows_query=ctx.query;
  if(result==JPW_STORE_VALID)break;
  REQUIRE(steps<1000000,"bounded test drain terminates");
 }
 if(ctx.result==JPW_STORE_VALID)REQUIRE(rows_query!=-1||steps==1,"large continuation retained journal cursor");return steps;
}
bool continuity_open(const string &key,JPWPersonalStoreContext &ctx,int rows=1024){
 if(JPWPersonalOpenBegin(key,false,"",0,0,ctx)!=JPW_STORE_BUSY)return false;continuity_drain(ctx,rows);return JPWPersonalReady(ctx);
}
void continuity_refused(const string &key){JPWPersonalStoreContext ctx;REQUIRE(!continuity_open(key,ctx,127)&&ctx.result==JPW_STORE_CORRUPT&&!ctx.audit_complete&&ctx.db==-1,"corruption fails closed after complete required prefix");JPWPersonalOpenCancel(ctx);}
void continuity_controller_reset(PersonalFixture &f,bool loaded){
 JPWPersonalOpenCancel(g_ph_store);JPWPersonalOpenCancel(g_ph_recovery);JPWPersonalContextReset(g_ph_store);JPWPersonalContextReset(g_ph_recovery);
 g_ph_context=f.key;g_ph_token=f.token;g_ph_loaded=loaded;g_ph_restored_once=loaded;g_ph_owner_conflict=false;g_ph_storage_failed=false;g_ph_revalidating=false;
 g_ph_next_open=0;g_ph_exclusive_file=123;g_ph_episodes=f.episodes;g_ph_current=f.current;g_ph_estimated_peak=f.estimated;g_ph_pending_current=false;g_ph_pending_estimated=false;g_ph_unwritten.clear();
 g_ph_gap=false;g_ph_gap_noted=false;g_ph_incomplete=false;g_ph_dirty=false;host_alert_calls=0;host_sound_calls=0;host_no_sl=true;host_identity_ok=true;
 if(loaded){g_ph_store=f.context;f.context.db=-1;f.context.writer=false;}
 host_controller_capture=f.capture;host_controller_subjects=f.subjects;host_controller_capture_ready=true;
}
void continuity_phase(const string &phase){
 PersonalFixture f;string mode=phase.find("WAL")!=string::npos?"WAL":"DELETE";
 JPWPersonalHash(phase.find("restart")!=string::npos ? "restart-process" : phase.find("snapshot")!=string::npos ? "snapshot-"+mode : "continuity-CONT-06",f.key);f.capture.account_key=f.key;
 if(phase=="live-busy-hold-reader"){JPWPersonalHash("live-writer-BUSY-retry",f.key);f.capture.account_key=f.key;}
 if(phase=="restart-seed"){continuity_seed(f,3001);return;}
 if(phase=="restart-crash-audit"||phase=="restart-crash-owner"){
  JPWPersonalStoreContext ctx;JPWPersonalOpenBegin(f.key,true,f.token,1000,1000000,ctx);JPWPersonalOpenStep(ctx,GetTickCount64(),25,31,1000,1000000);
  REQUIRE(ctx.transaction_active&&!ctx.writer&&!ctx.audit_complete,"fresh process crash starts partial audit");
  if(phase=="restart-crash-owner"){for(int n=0;n<1000&&ctx.phase!=JPW_PH_OWNER_COMMIT;n++)JPWPersonalOpenStep(ctx,GetTickCount64(),25,31,1000,1000000);REQUIRE(ctx.phase==JPW_PH_OWNER_COMMIT&&!ctx.writer,"crash after EOF before owner commit");}
  std::_Exit(99);
 }
 if(phase=="restart-recover"){JPWPersonalStoreContext ctx;JPWPersonalOpenBegin(f.key,true,f.token,1000,1000000,ctx);REQUIRE(ctx.expected_sequence==0&&!ctx.audit_complete,"reboot starts audit from row one");REQUIRE(host_personal_drain(ctx)&&ctx.expected_sequence==3001&&ctx.writer,"fresh reboot audits all original rows");std::vector<JPWPersonalEpisode> episodes;JPWPersonalPeak current,estimated;REQUIRE(JPWPersonalLoadAuditedFrom(ctx,episodes,current,estimated)&&episodes.size()==1&&episodes[0].next_wall==1060&&current.leverage==7,"fresh reboot retains deadline and original peak");JPWPersonalClose(ctx,1000,1000000);return;}
 if(phase.find("hold-reader")!=string::npos){JPWPersonalStoreContext ctx;REQUIRE(continuity_open(f.key,ctx),"fresh reader retained snapshot");continuity_gate("reader-ready");continuity_await_gate("reader-release");REQUIRE(JPWPersonalReadFinish(ctx,true),"fresh reader confirms snapshot");JPWPersonalOpenCancel(ctx);return;}
 int b=DatabaseOpen(JPWPersonalPath(f.key),DATABASE_OPEN_READWRITE);REQUIRE(b!=-1,"fresh mutation connection");
 if(phase=="try-reserved"){REQUIRE(!DatabaseExecute(b,"UPDATE ph_rows SET wall=1001 WHERE sequence=1")&&GetLastError()==ERR_DATABASE_BUSY,"separate process cannot mutate reserved audit");DatabaseClose(b);return;}
 REQUIRE(DatabaseExecute(b,"SELECT sequence FROM ph_meta WHERE id=1"),"fresh writer activates WAL before RO connection");continuity_gate("mutator-open");continuity_await_gate("mutation-start");REQUIRE(DatabaseExecute(b,"BEGIN IMMEDIATE")&&DatabaseExecute(b,"UPDATE ph_rows SET digest='broken' WHERE sequence=1"),"fresh process stage external generation");continuity_gate("mutation-ready");continuity_await_gate("commit-go");bool committed=DatabaseTransactionCommit(b);continuity_gate("commit-status",committed?"PASS":GetLastError()==ERR_DATABASE_BUSY?"BUSY":"ERROR");
 if(!committed){continuity_await_gate("commit-retry");REQUIRE(DatabaseTransactionCommit(b),"fresh DELETE commit after reader closes");}DatabaseClose(b);
}
